            ]
        if items["brown"]["状态"] == "success":
            items["brown"]["附加结果图"] = [
                value for value in (
                    derma_result.get("brown_base"),
                ) if value
            ]
        if items["uv_spots"]["状态"] == "success":
            items["uv_spots"]["附加结果图"] = [
                derma_result["purple_uv_base"]
            ]
        if items["porphyrin"]["状态"] == "success":
            items["porphyrin"]["附加结果图"] = [
                derma_result["purple_fluorescence_base"]
            ]
        acne = responses.get("acne", {})
        acne_result = acne.get("result", {})
        if acne.get("status") == "success":
            files = acne_result.get("results", {})
            items["acne"].update({
                "状态": "success",
                "主结果图": files.get("acne_circles"),
                "量化JSON": files.get("acne_summary") or acne_result.get("summary_path"),
