        for rel in item.get('附加结果图',[]):
            if not (sample/rel).is_file(): issues.append(f'{sample.name}:{key}:extra missing')
    red=list((sample/'七项检测/红区').glob('*'))
    brown=list((sample/'七项检测/棕区').glob('*'))
    if any(p.name.startswith('06_') for p in red): issues.append(f'{sample.name}:duplicate red')
    if any(p.name.startswith('02_VISIA') for p in brown): issues.append(f'{sample.name}:duplicate brown')
    purple=sample/'七项检测/紫区'
    if len([p for p in purple.iterdir() if p.suffix.lower() in {'.jpg','.png'}])!=4: issues.append(f'{sample.name}:purple image count')
