            if '/home/' in text or '/tmp/' in text or re.search(r'[A-Za-z]:[\\/]', text): issues.append(f'{sample.name}:absolute path:{p.relative_to(sample)}')
            if re.search(r'(?i)(model_path|weights|cuda:|gpu_name|audit|reason_code)', text): issues.append(f'{sample.name}:internal field:{p.relative_to(sample)}')
